final Map<String, Uint8List> _decoded = {};

Uint8List _u8(String b64) => base64Decode(b64);

/// Decodes once per photo, then caches: a base64Decode of a hundred-plus KB
/// string is not work a rebuild should repeat.
Uint8List _photo(String key, String b64) => _decoded[key] ??= _u8(b64);

/// The world region a country's police photo comes from, by ISO 3166-1
/// alpha-2 code (upper case). Null = the country has no photo, and the world
/// card simply shows the emergency lines without one.
String? _policeRegionFor(String iso) => switch (iso.toUpperCase()) {
      // West Africa
      'GH' || 'TG' || 'BJ' || 'BF' || 'CI' || 'LR' || 'SL' || 'GN' ||
      'GM' || 'SN' || 'ML' || 'NE' || 'BF' || 'GW' || 'CV' || 'MR' ||
      'NG' || 'ST' || 'SC' => 'west_africa',
      // East Africa
      'KE' || 'TZ' || 'UG' || 'ET' || 'RW' || 'SO' || 'DJ' || 'BI' ||
      'SS' || 'ER' || 'KM' || 'MG' || 'MU' || 'MW' || 'ZM' || 'ZW' => 'east_africa',
      // Southern Africa
      'ZA' || 'NA' || 'BW' || 'LS' || 'SZ' || 'MZ' => 'south_africa',
      // Europe
      'GB' || 'IE' || 'FR' || 'DE' || 'IT' || 'ES' || 'PT' || 'NL' ||
      'BE' || 'AT' || 'CH' || 'SE' || 'NO' || 'DK' || 'FI' || 'IS' ||
      'PL' || 'CZ' || 'SK' || 'HU' || 'RO' || 'BG' || 'GR' || 'HR' ||
      'SI' || 'RS' || 'BA' || 'MK' || 'AL' || 'ME' || 'LT' || 'LV' ||
      'EE' || 'RU' || 'UA' || 'BY' || 'MD' => 'europe',
      // The Americas
      'US' || 'CA' || 'MX' || 'BR' || 'AR' || 'CL' || 'CO' || 'PE' ||
      'VE' || 'EC' || 'BO' || 'PY' || 'UY' || 'PA' || 'CR' || 'GT' ||
      'DO' || 'CU' || 'JM' || 'HT' || 'TT' || 'HN' || 'SV' || 'NI' => 'americas',
      // Middle East and North Africa
      'AE' || 'SA' || 'QA' || 'KW' || 'BH' || 'OM' || 'EG' || 'MA' ||
      'DZ' || 'TN' || 'LY' || 'JO' || 'LB' || 'IL' || 'PS' || 'IQ' ||
      'IR' || 'TR' || 'SY' || 'YE' || 'SD' || 'AZ' || 'AM' || 'GE' => 'mena',
      // South Asia
      'IN' || 'PK' || 'BD' || 'LK' || 'NP' || 'BT' || 'MV' || 'AF' => 'south_asia',
      // East and Southeast Asia
      'SG' || 'ID' || 'MY' || 'TH' || 'PH' || 'VN' || 'CN' || 'JP' ||
      'KR' || 'KP' || 'TW' || 'HK' || 'MO' || 'KH' || 'LA' || 'MM' ||
      'BN' || 'MN' || 'KG' || 'KZ' || 'UZ' || 'TJ' || 'TM' => 'east_asia',
      _ => null,
    };

/// The police photo shown beside a country's emergency lines, or null.
Uint8List? policePhotoForCountry(String iso) => switch (_policeRegionFor(iso)) {
      'west_africa' => _photo('police_west_africa', _policeWestAfricaB64),
      'east_africa' => _photo('police_east_africa', _policeEastAfricaB64),
      'south_africa' => _photo('police_south_africa', _policeSouthAfricaB64),
      'europe' => _photo('police_europe', _policeEuropeB64),
      'americas' => _photo('police_americas', _policeAmericasB64),
      'mena' => _photo('police_mena', _policeMenaB64),
      'south_asia' => _photo('police_south_asia', _policeSouthAsiaB64),
      'east_asia' => _photo('police_east_asia', _policeEastAsiaB64),
      _ => null,
    };

/// The firefighter photo shown beside a country's emergency lines, or null.
/// Africa's own regions share the African photo; Asia and the Middle East
/// share the Asian one; everywhere else falls back to nothing.
Uint8List? firePhotoForCountry(String iso) => switch (_policeRegionFor(iso)) {
      'west_africa' || 'east_africa' || 'south_africa' => _photo('fire_africa', _fireAfricaB64),
      'europe' => _photo('fire_europe', _fireEuropeB64),
      'americas' => _photo('fire_americas', _fireAmericasB64),
      'mena' || 'south_asia' || 'east_asia' => _photo('fire_asia', _fireAsiaB64),
      _ => null,
    };
